WITH with_windows AS (SELECT id, customer_id, store_id, order_date, status, channel, amount, discount, shipping_fee, RANK() OVER (PARTITION BY customer_id, status ORDER BY discount ASC NULLS LAST) AS discount_rank, ROW_NUMBER() OVER (PARTITION BY channel ORDER BY order_date DESC, id ASC) AS event_seq, RANK() OVER (PARTITION BY customer_id, store_id ORDER BY amount DESC NULLS LAST) AS amount_rank, AVG(amount) OVER (PARTITION BY customer_id, store_id ORDER BY discount ASC, id ASC ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS amount_avg_3 FROM orders) SELECT s.id, s.store_id, s.status, s.amount, s.discount, s.shipping_fee, s.event_seq, s.amount_rank, s.amount_avg_3, CASE WHEN status RLIKE '^(RETURNED|SHIPPED)$' THEN 'EXTENDED' WHEN status RLIKE '^(COMPLETED|PENDING)$' THEN 'PRIORITY' ELSE 'CORE' END AS status_zone, (SELECT MIN(x.quantity) FROM inventory x WHERE x.store_id = s.store_id) AS min_inventory_quantity FROM with_windows s
